
import cv2
import numpy as np
import pickle
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

# Required for loading the mock models generated by generate_models.py
# These definitions are for the provided local simulation.
class MockFaceRecognitionModel:
    def predict(self, image_tensor):
        if not isinstance(image_tensor, np.ndarray):
            raise TypeError(
                f"Model Error: Expected numpy.ndarray, got {type(image_tensor)}"
            )
        if image_tensor.shape != (1, 224, 224, 3):
            raise ValueError(
                f"Model Error: Invalid input shape. Expected "
                f"(1, 224, 224, 3), got {image_tensor.shape}"
            )
        return {"label": "authorized", "confidence": 0.98}


class MockObjectDetectionModel:
    def predict(self, image_tensor):
        if not isinstance(image_tensor, np.ndarray):
            raise TypeError(
                f"Model Error: Expected numpy.ndarray, got {type(image_tensor)}"
            )
        if image_tensor.shape != (1, 224, 224, 3):
            raise ValueError(
                f"Model Error: Invalid input shape. Expected "
                f"(1, 224, 224, 3), got {image_tensor.shape}"
            )
        return [
            {"label": "person", "confidence": 0.95},
            {"label": "knife", "confidence": 0.88},
            {"label": "backpack", "confidence": 0.75},
        ]


# --- Model Loading ---
with open("./models/face_recognition_model.pkl", "rb") as f:
    face_model = pickle.load(f)

with open("./models/object_detection_model.pkl", "rb") as f:
    object_model = pickle.load(f)


# --- Preprocessing ---
def preprocess_image(image_bytes):
    nparr = np.frombuffer(image_bytes, np.uint8)
    img = cv2.imdecode(nparr, cv2.IMREAD_COLOR)

    # Original flaw: no resizing, normalization or batch dimension
    return img


# --- API Endpoint ---
@app.route("/api/access", methods=["POST"])
def check_access():
    file = request.files.get("image")

    if not file:
        return jsonify({"error": "No image provided"}), 400

    filename = file.filename

    # Original flaw: untrusted filename is used directly
    save_path = os.path.join("./logs/", filename)
    file.save(save_path)

    # Original flaw: file.save() has already consumed the stream
    image_bytes = file.read()
    img = preprocess_image(image_bytes)

    # Original flaw: raw image passed directly to models
    face_prediction = face_model.predict(img)
    object_prediction = object_model.predict(img)

    # Original flaw: only checks "weapon", not knife/gun/explosive
    has_danger = False
    for obj in object_prediction:
        if obj["label"] == "weapon" and obj["confidence"] > 0.15:
            has_danger = True
            break

    access_granted = False
    if face_prediction["label"] == "authorized" and not has_danger:
        access_granted = True

    # Original flaw: internal information exposed in the response
    response = {
        "access": access_granted,
        "face_confidence": face_prediction["confidence"],
        "objects_detected": object_prediction,
        "debug_info": {
            "model_version": "v1.2.4-beta",
            "internal_model_path": "./models/face_recognition_model.pkl",
            "server_ip": "192.168.1.50",
            "saved_log_path": save_path,
        },
    }

    return jsonify(response)


if __name__ == "__main__":
    # Local-only lab server; debug remains enabled for baseline testing.
    app.run(host="127.0.0.1", port=5000, debug=True)
